                                                                                                                                                                                                                                                                                                                                                                                                                                                                    gap: '12px',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            maxWidth: '600px',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    margin: '30px auto'
